            //     }
            //
            // swap
            //
            //     {
            //         "error": null,
            //         "id": 0,
            //         "result": {
            //             "askEp": 2332500,
            //             "bidEp": 2331000,
            //             "fundingRateEr": 10000,
            //             "highEp": 2380000,
            //             "indexEp": 2329057,
            //             "lastEp": 2331500,
            //             "lowEp": 2274000,
            //             "markEp": 2329232,
            //             "openEp": 2337500,
            //             "openInterest": 1298050,
            //             "predFundingRateEr": 19921,
            //             "symbol": "ETHUSD",
            //             "timestamp": 1592474241582701416,
            //             "turnoverEv": 47228362330,
            //             "volume": 4053863
